begin;
create extension if not exists pgtap with schema extensions;
select plan(14);
update public.communication_rules set grace_seconds=0;
-- Start from a single controlled, due, high-priority source.
update public.reminders set due_at=now()-interval '1 hour',revision=999 where id='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1';
select is((select revision::integer from public.reminders where id='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1'),2,'caller cannot forge revision');
select is(public.claim_escalation_attempt('{"kind":"reminder","id":"aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1","revision":"2","channel":"imessage","stage":"initial"}'),null::jsonb,'disabled outreach blocked');
update public.profiles set outreach_enabled=true,destination='simulation-only',opted_in_channels='{imessage,facetime}';
select is(public.claim_escalation_attempt('{"kind":"reminder","id":"aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1","revision":"2","channel":"imessage","stage":"initial"}'),null::jsonb,'unverified destination blocked');
update public.profiles set verified_at=now(),timezone='UTC';
update public.communication_rules set quiet_start=(now()-interval '1 hour')::time,quiet_end=(now()+interval '1 hour')::time;
select is(public.claim_escalation_attempt('{"kind":"reminder","id":"aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1","revision":"2","channel":"imessage","stage":"initial"}'),null::jsonb,'quiet hours blocked');
update public.communication_rules set quiet_start=null,quiet_end=null;
update public.profiles set opted_in_channels='{}';
select is(public.claim_escalation_attempt('{"kind":"reminder","id":"aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1","revision":"2","channel":"imessage","stage":"initial"}'),null::jsonb,'channel consent required');
update public.profiles set opted_in_channels='{imessage,facetime}';
select is(public.claim_escalation_attempt('{"kind":"reminder","id":"aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa2","revision":"1","channel":"imessage","stage":"initial"}'),null::jsonb,'future reminders blocked');
select is(public.claim_escalation_attempt('{"kind":"reminder","id":"aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1","revision":"2","channel":"imessage","stage":"fallback"}'),null::jsonb,'forged stage blocked');
select isnt(public.claim_escalation_attempt('{"kind":"home_event","id":"cccccccc-cccc-4ccc-8ccc-ccccccccccc1","revision":"1","channel":"imessage","stage":"initial"}'),null::jsonb,'eligible home event claim');
select is(public.claim_escalation_attempt('{"kind":"home_event","id":"cccccccc-cccc-4ccc-8ccc-ccccccccccc2","revision":"1","channel":"imessage","stage":"initial"}'),null::jsonb,'observation alone cannot trigger outreach');
insert into public.check_ins(id,user_id,due_at,enabled,priority) values('dddddddd-dddd-4ddd-8ddd-ddddddddddd1','11111111-1111-4111-8111-111111111111',now()-interval '1 hour',true,'medium');
select is(public.claim_escalation_attempt('{"kind":"check_in","id":"dddddddd-dddd-4ddd-8ddd-ddddddddddd1","revision":"1","channel":"imessage","stage":"initial"}'),null::jsonb,'check-in requires consent');
update public.check_ins set consented_at=now();
select isnt(public.claim_escalation_attempt('{"kind":"check_in","id":"dddddddd-dddd-4ddd-8ddd-ddddddddddd1","revision":"2","channel":"imessage","stage":"initial"}'),null::jsonb,'consented check-in claim');
update public.communication_rules set max_calls_per_day=1,critical_channel='facetime';
select isnt(public.claim_escalation_attempt('{"kind":"reminder","id":"aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa3","revision":"1","channel":"facetime","stage":"initial"}'),null::jsonb,'first call reserves daily cap');
insert into public.reminders(id,user_id,title,due_at,priority) values('eeeeeeee-eeee-4eee-8eee-eeeeeeeeeee1','22222222-2222-4222-8222-222222222222','Second call',now()-interval '1 hour','critical');
select is(public.claim_escalation_attempt('{"kind":"reminder","id":"eeeeeeee-eeee-4eee-8eee-eeeeeeeeeee1","revision":"1","channel":"facetime","stage":"initial"}'),null::jsonb,'second source cannot exceed cap');
select throws_ok($$insert into public.notification_attempts(user_id,reminder_id,revision,channel,stage,idempotency_key) values('22222222-2222-4222-8222-222222222222','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1',2,'imessage','initial','cross-owner')$$,'23503',null,'cross-owner foreign key rejected even for backend');
select * from finish();
rollback;
